pub unsafe fn create_dps(instance:HINSTANCE,main_hwnd:HWND,features:Arc<RwLock<FeatureSettings>>,paths:AppPaths)->Result<HWND,String>{create(instance,main_hwnd,features,paths,Kind::Dps)}
pub unsafe fn create_mechanics(instance:HINSTANCE,main_hwnd:HWND,features:Arc<RwLock<FeatureSettings>>,paths:AppPaths)->Result<HWND,String>{create(instance,main_hwnd,features,paths,Kind::Mechanics)}
unsafe fn create(instance:HINSTANCE,main_hwnd:HWND,features:Arc<RwLock<FeatureSettings>>,paths:AppPaths,kind:Kind)->Result<HWND,String>{
let class_name=if kind==Kind::Dps{DPS_CLASS}else{MECH_CLASS};let class=wide(class_name);let wc=WNDCLASSW{lpfnWndProc:Some(wnd_proc),hInstance:instance,hCursor:LoadCursorW(null_mut(),IDC_ARROW),lpszClassName:class.as_ptr(),..std::mem::zeroed()};if RegisterClassW(&wc)==0&&GetLastError()!=1410{return Err(format!("RegisterClassW({class_name}) failed: {}",GetLastError()));}
let snapshot=features.read().map(|x|x.clone()).unwrap_or_default();let layout=if kind==Kind::Dps{snapshot.dps.clone()}else{snapshot.mechanics.clone()};let x=if layout.x==i32::MIN{CW_USEDEFAULT}else{layout.x};let y=if layout.y==i32::MIN{CW_USEDEFAULT}else{layout.y};let state=Box::new(State{kind,main_hwnd,paths,features,dps:DpsSnapshot::default(),mechanics:MechanicSnapshot::default(),collapsed:false,expanded:RECT{left:x,top:y,right:x.saturating_add(layout.width),bottom:y.saturating_add(layout.height)},scroll:0,sort_mode:SortMode::Damage,detail_hwnd:null_mut(),detail_uid:0,settings_hwnd:null_mut()});let ptr=Box::into_raw(state);let title=wide(if kind==Kind::Dps{"ReadyAlert DPS Meter"}else{"ReadyAlert Dungeon Mechanics"});let hwnd=CreateWindowExW(WS_EX_TOOLWINDOW|WS_EX_LAYERED|WS_EX_TOPMOST,class.as_ptr(),title.as_ptr(),WS_POPUP|WS_THICKFRAME,x,y,layout.width,layout.height,null_mut(),null_mut(),instance,ptr.cast::<c_void>());if hwnd.is_null(){drop(Box::from_raw(ptr));return Err(format!("CreateWindowExW({class_name}) failed: {}",GetLastError()));}apply_opacity(hwnd,layout.opacity);SetWindowPos(hwnd,HWND_TOPMOST,0,0,0,0,SWP_NOACTIVATE|SWP_NOMOVE|SWP_NOSIZE);Ok(hwnd)}
pub unsafe fn update_dps(hwnd:HWND,snapshot:DpsSnapshot){with_state(hwnd,|state|{if snapshot.encounter_ms<state.dps.encounter_ms&&!state.features.read().map(|f|f.meter.remember_scroll).unwrap_or(false){state.scroll=0;}if !state.detail_hwnd.is_null()&&IsWindow(state.detail_hwnd)!=0&&state.detail_uid!=0{if let Some(row)=snapshot.rows.iter().find(|row|row.uid==state.detail_uid).cloned(){update_detail(state.detail_hwnd,row);}}state.dps=snapshot;state.scroll=state.scroll.min(state.dps.rows.len().saturating_sub(1));});InvalidateRect(hwnd,null(),0);}
pub unsafe fn update_mechanics(hwnd:HWND,snapshot:MechanicSnapshot){with_state(hwnd,|state|state.mechanics=snapshot);InvalidateRect(hwnd,null(),0);}
pub unsafe fn expand(hwnd:HWND){with_state(hwnd,|state|if state.collapsed{expand_state(hwnd,state)});}
unsafe extern "system" fn wnd_proc(hwnd:HWND,msg:u32,wparam:WPARAM,lparam:LPARAM)->LRESULT{if msg==WM_NCCREATE{let create=lparam as *const CREATESTRUCTW;if !create.is_null(){SetWindowLongPtrW(hwnd,GWLP_USERDATA,(*create).lpCreateParams as isize);}}let ptr=GetWindowLongPtrW(hwnd,GWLP_USERDATA)as *mut State;match msg{WM_ERASEBKGND=>1,WM_PAINT=>{if !ptr.is_null(){paint(hwnd,&mut*ptr);}0},WM_SIZE=>{if !ptr.is_null(){clamp_scroll(hwnd,&mut*ptr);}InvalidateRect(hwnd,null(),0);0},WM_LBUTTONDOWN=>{if !ptr.is_null(){on_click(hwnd,&mut*ptr,lparam);}0},WM_MOUSEWHEEL=>{if !ptr.is_null(){on_wheel(hwnd,&mut*ptr,wparam);}0},WM_EXITSIZEMOVE=>{if !ptr.is_null(){save_bounds(hwnd,&mut*ptr);clamp_scroll(hwnd,&mut*ptr);}0},WM_NCDESTROY=>{SetWindowLongPtrW(hwnd,GWLP_USERDATA,0);if !ptr.is_null(){let state=&mut*ptr;for child in[state.detail_hwnd,state.settings_hwnd]{if !child.is_null()&&IsWindow(child)!=0{DestroyWindow(child);}}drop(Box::from_raw(ptr));}DefWindowProcW(hwnd,msg,wparam,lparam)},_=>DefWindowProcW(hwnd,msg,wparam,lparam)}}
unsafe fn on_click(hwnd:HWND,state:&mut State,lparam:LPARAM){if state.collapsed{expand_state(hwnd,state);return;}let x=lo_signed(lparam);let y=hi_signed(lparam);let mut rc:RECT=std::mem::zeroed();GetClientRect(hwnd,&mut rc);if y<TOOLBAR_H{if x>=rc.right-BUTTON_W{PostMessageW(state.main_hwnd,0x0111,if state.kind==Kind::Dps{CMD_HIDE_DPS as usize}else{CMD_HIDE_MECHANICS as usize},0);}else if x>=rc.right-BUTTON_W*2{collapse(hwnd,state);}else if x>=rc.right-BUTTON_W*3{open_feature_settings(hwnd,state);}else{drag_window(hwnd);}return;}if state.kind==Kind::Dps&&y<dps_rows_top(){let control_y=TOOLBAR_H+4;if y>=control_y&&y<control_y+23{match x{8..=78=>state.sort_mode=SortMode::Damage,83..=148=>state.sort_mode=SortMode::Heal,153..=218=>state.sort_mode=SortMode::Tank,225..=298=>{crate::telemetry::request_manual_reset();state.dps=DpsSnapshot::default();state.scroll=0;},_=>{}}InvalidateRect(hwnd,null(),0);}return;}if state.kind==Kind::Dps{if let Some(row)=dps_row_at(hwnd,state,y){open_detail(hwnd,state,row);}}}
unsafe fn on_wheel(hwnd:HWND,state:&mut State,wparam:WPARAM){if state.collapsed{return;}let delta=(((wparam>>16)&0xffff)as u16 as i16)as i32;if delta==0{return;}let steps=((delta.abs()/120).max(1)as usize)*3;if delta>0{state.scroll=state.scroll.saturating_sub(steps);}else{state.scroll=state.scroll.saturating_add(steps);}clamp_scroll(hwnd,state);InvalidateRect(hwnd,null(),0);}
unsafe fn paint(hwnd:HWND,state:&mut State){let mut ps:PAINTSTRUCT=std::mem::zeroed();let hdc=BeginPaint(hwnd,&mut ps);if hdc.is_null(){return;}let mut rc:RECT=std::mem::zeroed();GetClientRect(hwnd,&mut rc);fill(hdc,&rc,rgb(18,22,27));SelectObject(hdc,GetStockObject(DEFAULT_GUI_FONT));SetBkMode(hdc,TRANSPARENT as i32);if state.collapsed{SetTextColor(hdc,rgb(99,199,255));draw(hdc,if state.kind==Kind::Dps{"D"}else{"M"},rc,DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);EndPaint(hwnd,&ps);return;}paint_toolbar(hdc,rc,state);match state.kind{Kind::Dps=>paint_dps(hdc,rc,state),Kind::Mechanics=>paint_mechanics(hdc,rc,state)}EndPaint(hwnd,&ps);}
unsafe fn paint_toolbar(hdc:HDC,rc:RECT,state:&State){let toolbar=RECT{left:0,top:0,right:rc.right,bottom:TOOLBAR_H};fill(hdc,&toolbar,rgb(23,28,35));fill(hdc,&RECT{left:0,top:TOOLBAR_H-2,right:rc.right,bottom:TOOLBAR_H},rgb(63,133,255));SetTextColor(hdc,rgb(231,237,244));draw(hdc,&toolbar_title(state),RECT{left:10,top:0,right:rc.right-BUTTON_W*3-4,bottom:TOOLBAR_H},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);SetTextColor(hdc,rgb(170,183,199));draw(hdc,"S",RECT{left:rc.right-BUTTON_W*3,top:0,right:rc.right-BUTTON_W*2,bottom:TOOLBAR_H},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);draw(hdc,"◀",RECT{left:rc.right-BUTTON_W*2,top:0,right:rc.right-BUTTON_W,bottom:TOOLBAR_H},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);draw(hdc,"×",RECT{left:rc.right-BUTTON_W,top:0,right:rc.right,bottom:TOOLBAR_H},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);}
fn toolbar_title(state:&State)->String{if state.kind==Kind::Mechanics{return"Dungeon Mechanics".into();}let show_target=state.features.read().map(|f|f.meter.show_target).unwrap_or(true);if !show_target{return format!("DPS Meter  {}",format_time(state.dps.encounter_ms));}let Some(target)=state.dps.target.as_ref()else{return format!("DPS Meter  {}",format_time(state.dps.encounter_ms));};let hp=if target.max_hp>0{format!("{:.1}%",(target.hp.max(0)as f64*100.0/target.max_hp as f64).clamp(0.0,100.0))}else{"?%".into()};format!("DPS Meter  {}  |  {} {}",format_time(state.dps.encounter_ms),target.name,hp)}
unsafe fn paint_dps(hdc:HDC,rc:RECT,state:&State){let settings=state.features.read().map(|x|x.clone()).unwrap_or_default();let control_top=TOOLBAR_H+4;paint_tab(hdc,8,control_top,70,"Damage",state.sort_mode==SortMode::Damage);paint_tab(hdc,83,control_top,65,"Heal",state.sort_mode==SortMode::Heal);paint_tab(hdc,153,control_top,65,"Tank",state.sort_mode==SortMode::Tank);paint_tab(hdc,225,control_top,73,"Reset",false);SetTextColor(hdc,rgb(145,160,180));draw(hdc,&format!("Total {}   Heal {}   Taken {}",compact(state.dps.total_damage as f64),compact(state.dps.total_healing as f64),compact(state.dps.total_damage_taken as f64)),RECT{left:304,top:control_top,right:rc.right-8,bottom:control_top+23},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);let rows=sorted_rows(&state.dps,state.sort_mode);let top=dps_rows_top();let visible=visible_dps_rows(rc.bottom);if rows.is_empty(){SetTextColor(hdc,rgb(132,145,162));draw(hdc,"Waiting for party / combat data...",RECT{left:10,top:top+18,right:rc.right-10,bottom:top+58},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);return;}for(screen_i,row)in rows.iter().skip(state.scroll).take(visible).enumerate(){let rank=state.scroll+screen_i+1;let y=top+screen_i as i32*DPS_ROW_H;let r=RECT{left:6,top:y,right:rc.right-8,bottom:y+DPS_ROW_H-2};let bg=spec_color(row);fill(hdc,&r,bg);if row.is_local{outline(hdc,r,rgb(212,175,55),2);}let base_text=text_on(bg);SetTextColor(hdc,base_text);draw(hdc,&rank.to_string(),RECT{left:r.left+5,top:r.top,right:r.left+28,bottom:r.bottom},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);let mut x=r.left+30;if settings.meter.show_imagines{for badge in row.imagines.iter().take(2){paint_badge(hdc,x,r.top+5,badge);x+=BADGE_W+BADGE_GAP;}}let metric_area=235;let identity_right=(r.right-metric_area).max(x+80);let name_right=(x+((identity_right-x)*45/100)).max(x+70);SetTextColor(hdc,if row.is_dead{rgb(255,45,45)}else{base_text});draw(hdc,&row.name,RECT{left:x,top:r.top,right:name_right,bottom:r.bottom},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);SetTextColor(hdc,base_text);draw(hdc,&identity_tail(row),RECT{left:name_right+5,top:r.top,right:identity_right,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);let mut metric_x=identity_right+5;SetTextColor(hdc,base_text);draw(hdc,&primary_metric(row,state.sort_mode),RECT{left:metric_x,top:r.top,right:metric_x+66,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);metric_x+=69;if settings.meter.show_damage_share{SetTextColor(hdc,rgb(255,70,70));draw_percent(hdc,row.damage_share,metric_x,r);metric_x+=52;}if settings.meter.show_healing_share{SetTextColor(hdc,rgb(40,215,100));draw_percent(hdc,row.healing_share,metric_x,r);metric_x+=52;}if settings.meter.show_tank_share{SetTextColor(hdc,rgb(35,145,255));draw_percent(hdc,row.tank_share,metric_x,r);metric_x+=52;}if settings.meter.show_deaths&&row.deaths>0{SetTextColor(hdc,rgb(255,45,45));draw(hdc,&format!("D{}",row.deaths),RECT{left:metric_x,top:r.top,right:r.right-4,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);}}paint_scrollbar(hdc,rc,rows.len(),visible,state.scroll,top);}
unsafe fn draw_percent(hdc:HDC,value:f64,x:i32,r:RECT){draw(hdc,&format!("{value:.1}%"),RECT{left:x,top:r.top,right:x+50,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);}
fn primary_metric(row:&DpsRow,mode:SortMode)->String{match mode{SortMode::Damage=>format!("{}/s",compact(row.dps)),SortMode::Heal=>compact(row.healing as f64),SortMode::Tank=>compact(row.damage_taken as f64)}}
fn sorted_rows(snapshot:&DpsSnapshot,mode:SortMode)->Vec<&DpsRow>{let mut rows:Vec<_>=snapshot.rows.iter().collect();rows.sort_by(|a,b|{let order=match mode{SortMode::Damage=>b.damage.cmp(&a.damage),SortMode::Heal=>b.healing.cmp(&a.healing),SortMode::Tank=>b.damage_taken.cmp(&a.damage_taken)};order.then_with(||a.name.cmp(&b.name))});rows}
unsafe fn paint_badge(hdc:HDC,x:i32,y:i32,badge:&ImagineBadge){let r=RECT{left:x,top:y,right:x+BADGE_W,bottom:y+19};fill(hdc,&r,badge_color(&badge.icon_key));SetTextColor(hdc,rgb(248,250,252));let short=if badge.icon_key.trim().is_empty()||badge.icon_key.eq_ignore_ascii_case("BI"){"BI"}else{badge.icon_key.as_str()};let label=if badge.tier>0{format!("{}{}",short,badge.tier)}else{short.to_string()};draw(hdc,&label,r,DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);}
unsafe fn paint_mechanics(hdc:HDC,rc:RECT,state:&State){let features=state.features.read().map(|x|x.clone()).unwrap_or_default();let tracked:Vec<_>=features.mechanic_attributes.tracked.iter().filter_map(|id|state.mechanics.tracked_attributes.iter().find(|attr|attr.attr_id==*id)).collect();let mut top=TOOLBAR_H+5;if !tracked.is_empty(){let strip=RECT{left:6,top,right:rc.right-6,bottom:top+MECH_ATTR_H-3};fill(hdc,&strip,rgb(27,32,39));let width=((strip.right-strip.left)/tracked.len()as i32).max(60);for(i,attr)in tracked.iter().enumerate(){let left=strip.left+i as i32*width;SetTextColor(hdc,rgb(218,227,238));draw(hdc,&format!("{} {}",attr.label,compact_attr(attr.value)),RECT{left:left+2,top:strip.top,right:(left+width-2).min(strip.right),bottom:strip.bottom},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);}top+=MECH_ATTR_H;}let consumables=RECT{left:6,top,right:rc.right-6,bottom:top+MECH_CONSUMABLE_H-4};fill(hdc,&consumables,rgb(23,28,34));SetTextColor(hdc,rgb(215,224,235));draw(hdc,&consumable_line("Food",state.mechanics.food.as_ref()),RECT{left:consumables.left+8,top:consumables.top,right:consumables.right-8,bottom:consumables.top+20},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);draw(hdc,&consumable_line("Serum",state.mechanics.serum.as_ref()),RECT{left:consumables.left+8,top:consumables.top+20,right:consumables.right-8,bottom:consumables.bottom},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);top+=MECH_CONSUMABLE_H;let now=now_ms();let active:Vec<_>=state.mechanics.rows.iter().filter(|row|row.persistent||row.expires_unix_ms<=0||row.expires_unix_ms>now).collect();let visible=((rc.bottom-top)/MECH_ROW_H).max(0)as usize;if active.is_empty(){SetTextColor(hdc,rgb(132,145,162));draw(hdc,"No active mechanic",RECT{left:10,top:top+18,right:rc.right-10,bottom:top+58},DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);return;}for(screen_i,row)in active.iter().skip(state.scroll).take(visible).enumerate(){let y=top+screen_i as i32*MECH_ROW_H;let r=RECT{left:6,top:y,right:rc.right-8,bottom:y+MECH_ROW_H-3};fill(hdc,&r,if screen_i%2==0{rgb(28,33,40)}else{rgb(24,29,35)});let accent=if row.priority>=3{rgb(255,99,99)}else{rgb(99,199,255)};fill(hdc,&RECT{left:r.left,top:r.top,right:r.left+3,bottom:r.bottom},accent);let label=match&row.target{Some(target)if!target.trim().is_empty()=>format!("{}  •  {}",row.label,target),_=>row.label.clone()};SetTextColor(hdc,rgb(238,242,247));draw(hdc,&label,RECT{left:r.left+10,top:r.top,right:r.right-75,bottom:r.bottom},DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX|DT_END_ELLIPSIS);SetTextColor(hdc,accent);draw(hdc,&mechanic_timer(row.expires_unix_ms,row.persistent,now),RECT{left:r.right-70,top:r.top,right:r.right-8,bottom:r.bottom},DT_RIGHT|DT_VCENTER|DT_SINGLELINE|DT_NOPREFIX);}paint_scrollbar(hdc,rc,active.len(),visible,state.scroll,top);}
fn consumable_line(label:&str,status:Option<&ConsumableStatus>)->String{let Some(status)=status else{return format!("{label}: None");};let timer=if status.expires_unix_ms>0{let left=status.expires_unix_ms.saturating_sub(now_ms()).max(0)as u64;format!("  {}",format_countdown(left))}else{String::new()};format!("{label}: {}{}",status.name,timer)}
fn mechanic_timer(expires:i64,persistent:bool,now:i64)->String{if persistent||expires<=0{"LIVE".into()}else{format!("{:.1}s",expires.saturating_sub(now).max(0)as f64/1000.0)}}
unsafe fn paint_scrollbar(hdc:HDC,rc:RECT,total:usize,visible:usize,scroll:usize,top:i32){if total<=visible||visible==0{return;}let track_top=top+2;let track_bottom=rc.bottom-5;let track_h=(track_bottom-track_top).max(20);fill(hdc,&RECT{left:rc.right-5,top:track_top,right:rc.right-2,bottom:track_bottom},rgb(45,52,61));let thumb_h=((track_h as f64*visible as f64/total as f64)as i32).clamp(16,track_h);let max_scroll=total.saturating_sub(visible).max(1);let pos=((track_h-thumb_h)as f64*scroll.min(max_scroll)as f64/max_scroll as f64)as i32;fill(hdc,&RECT{left:rc.right-6,top:track_top+pos,right:rc.right-1,bottom:track_top+pos+thumb_h},rgb(99,199,255));}
unsafe fn dps_row_at(hwnd:HWND,state:&State,y:i32)->Option<DpsRow>{let mut rc:RECT=std::mem::zeroed();GetClientRect(hwnd,&mut rc);let top=dps_rows_top();if y<top||y>=rc.bottom{return None;}let screen_i=((y-top)/DPS_ROW_H)as usize;if screen_i>=visible_dps_rows(rc.bottom){return None;}sorted_rows(&state.dps,state.sort_mode).get(state.scroll+screen_i).map(|row|(*row).clone())}
