fn badge_color(key:&str)->u32{match key{"TN"=>rgb(105,166,230),"BL"=>rgb(190,112,92),"AI"=>rgb(100,184,145),_=>rgb(104,112,130)}}
fn compact(value:f64)->String{let abs=value.abs();if abs>=1_000_000_000.0{format!("{:.2}B",value/1_000_000_000.0)}else if abs>=1_000_000.0{format!("{:.2}M",value/1_000_000.0)}else if abs>=1_000.0{format!("{:.1}K",value/1_000.0)}else{format!("{value:.0}")}}
fn compact_attr(value:i64)->String{if value.abs()>=100_000{format!("{:.1}K",value as f64/1000.0)}else{value.to_string()}}
fn score(value:i64)->String{if value.abs()>=10_000{format!("{}k",(value as f64/1000.0).round()as i64)}else{value.to_string()}}
fn format_time(ms:u64)->String{let seconds=ms/1000;format!("{}:{:02}",seconds/60,seconds%60)}
fn format_countdown(ms:u64)->String{let seconds=(ms+999)/1000;if seconds>=60{format!("{}:{:02}",seconds/60,seconds%60)}else{format!("{}s",seconds)}}
fn now_ms()->i64{SystemTime::now().duration_since(UNIX_EPOCH).map(|duration|duration.as_millis().min(i64::MAX as u128)as i64).unwrap_or(0)}
fn lo_signed(value:LPARAM)->i32{(value as u16 as i16)as i32}
fn hi_signed(value:LPARAM)->i32{(((value>>16)as u16)as i16)as i32}
fn hex_color(rgb_hex:u32)->u32{rgb(((rgb_hex>>16)&0xff)as u8,((rgb_hex>>8)&0xff)as u8,(rgb_hex&0xff)as u8)}
fn rgb(r:u8,g:u8,b:u8)->u32{u32::from(r)|(u32::from(g)<<8)|(u32::from(b)<<16)}
fn wide(text:&str)->Vec<u16>{text.encode_utf16().chain(std::iter::once(0)).collect()}
#[cfg(test)]mod tests{use super::*;#[test]fn requested_spec_colors_are_exact(){let row=|name:&str|DpsRow{subprofession_name:name.into(),..DpsRow::default()};assert_eq!(spec_color(&row("Iaido")),hex_color(0x9b6cf0));assert_eq!(spec_color(&row("Formless")),hex_color(0xff6d3a));assert_eq!(spec_color(&row("Crimson")),hex_color(0xc41e00));assert_eq!(spec_color(&row("Concerto")),hex_color(0x9f1322));}#[test]fn sort_modes_order_expected_metric(){let snapshot=DpsSnapshot{rows:vec![DpsRow{name:"A".into(),damage:5,healing:50,damage_taken:1,..DpsRow::default()},DpsRow{name:"B".into(),damage:50,healing:5,damage_taken:100,..DpsRow::default()}],..DpsSnapshot::default()};assert_eq!(sorted_rows(&snapshot,SortMode::Damage)[0].name,"B");assert_eq!(sorted_rows(&snapshot,SortMode::Heal)[0].name,"A");assert_eq!(sorted_rows(&snapshot,SortMode::Tank)[0].name,"B");}}
